644 {
  "key": "/Applications/DevSwarm.app/Contents/Resources/cli/hivecontrol|1791996847000|242",
  "checkedAt": "2026-10-17T05:00:44.638Z",
  "probe": {
    "present": true,
    "bin": "/Applications/DevSwarm.app/Contents/Resources/cli/hivecontrol",
    "version": "2.5.7",
    "versionSource": "hivecontrol",
    "verbs": {
      "children": {
        "usage": "[options]",
        "desc": "List direct children of the current workspace (the workspaces it created, plus any with no resolvable messaging parent whose source branch is your current branch) as a flat JSON array. Each row carries archived state (isArchived, archivedAt), agent (whether its AI agent is alive now) and terminals; rows have no terminalId, which is deprecated. With --tree, render the git subtree instead: you plus everything branched off you, transitively. The two differ on purpose — the flat list answers what you spawned, the tree shows where things sit. Errors when not inside a DevSwarm workspace."
      },
      "list": {
        "usage": "[options]",
        "desc": "List every workspace in the current repository as a flat JSON array. Each row carries archived state (isArchived, archivedAt), agent (whether its AI agent is alive now) and terminals; rows have no terminalId, which is deprecated. Pass --tree for an ASCII hierarchy, or use 'workspace children' to scope to the current workspace."
      },
      "info": {
        "usage": "[idOrBranch]",
        "desc": "Get workspace details. Defaults to the current workspace; pass a workspace ID or branch name to look up a different one. Returns JSON with branch, path, aiAgent, archived state (isArchived, archivedAt), startup (whether the workspace came up this app session), agent (whether its AI agent is alive now) and terminals (every terminal it holds). terminalId is deprecated and does not show whether the agent is alive; read agent and terminals instead."
      },
      "create": {
        "usage": "[options] <branch>",
        "desc": "Create a new workspace. You become its messaging parent (message-parent / message-child), whatever --source says; --source sets the git base and where it sits in the sidebar."
      },
      "update-title": {
        "usage": "[options] <title>",
        "desc": "Update the display title for a workspace"
      },
      "tag": {
        "usage": "",
        "desc": "Read and write tags on a workspace. Tags are labels shared with the sidebar — `tag:<name>` filters on them there. A tag is scoped either to this repository or to every local one; every row reports its own `scope`."
      },
      "view": {
        "usage": "",
        "desc": "Read the user's sidebar Views — the saved sections they watch. Views are created in the sidebar; this is a read-only surface."
      },
      "pane": {
        "usage": "",
        "desc": "List or create AI panes in the current Workspace. Pane IDs are stable message addresses."
      },
      "archive": {
        "usage": "hivecontrol workspace archive [options] [idOrBranch]",
        "desc": "Archive a Workspace without deleting its worktree. Defaults to the current Workspace; accepts a Workspace ID or branch. Repeats are safe.",
        "args": [
          {
            "name": "idOrBranch",
            "required": false
          }
        ],
        "flags": [
          "-h",
          "--help"
        ]
      },
      "delete": {
        "usage": "hivecontrol workspace delete [options] [idOrBranch]",
        "desc": "Permanently delete an archived Workspace. Refuses active Workspaces and any uncommitted parent or Multi-Repo member worktree changes. Refuses with exit 5, before sending anything, when the running DevSwarm app is too old to enforce these checks.",
        "args": [
          {
            "name": "idOrBranch",
            "required": false
          }
        ],
        "flags": [
          "--reparent-children",
          "-h",
          "--help"
        ]
      },
      "check-merge": {
        "usage": "",
        "desc": "Check merge status and get paths to source/current directories. Returns JSON with isMergeable, hasConflicts, targetDirectoryClean, sourceBranchCheckedOut, and file paths (sourceBranchPath is null when the source branch is not checked out anywhere). Run from your workspace - do not cd elsewhere."
      },
      "merge-from-source": {
        "usage": "",
        "desc": "Merge source branch INTO current workspace. Run from your workspace - do not cd elsewhere. If WORKING_DIRECTORY_NOT_CLEAN, explain to user and ask before proceeding."
      },
      "merge-into-source": {
        "usage": "",
        "desc": "Merge current workspace INTO source branch. Needs the source branch checked out in a worktree (e.g. the Primary workspace) and is refused otherwise. Run from your workspace - do not cd elsewhere. If WORKING_DIRECTORY_NOT_CLEAN, explain to user and ask before proceeding."
      },
      "update-base": {
        "usage": "[options]",
        "desc": "Update a workspace's recorded sourceBranch. Without --source, reads the workspace's open PR (if there's exactly one) and offers to apply its target. With --source <branch>, skips detection and writes the value directly (backend cycle check authoritative). Defaults to the current workspace."
      },
      "message-sibling": {
        "usage": "[options] <target-pane> <message>",
        "desc": "Send a message to another active AI pane in the current Workspace by stable pane ID or label (the oldest active pane wins when several share it)."
      },
      "message-workspace": {
        "usage": "[options] <target-workspace> <message>",
        "desc": "Send a message to any non-archived Workspace without a parent/child requirement. UUIDs may cross repositories; branch names use the current repository."
      },
      "reactivate-child": {
        "usage": "[options] <target-branch> <prompt>",
        "desc": "Wake an existing non-archived direct child Workspace and queue a durable pane-addressed prompt. This does not create or unarchive a Workspace."
      },
      "set-parent": {
        "usage": "[options] [parent]",
        "desc": "Set which workspace this one messages with message-parent. Takes a workspace id or branch, or --clear. Does not move the workspace in the sidebar unless you pass --also-set-source. Defaults to the current workspace."
      },
      "message-child": {
        "usage": "[options] <target-branch> <message>",
        "desc": "Send a message to a child workspace"
      },
      "message-parent": {
        "usage": "[options] <message>",
        "desc": "Send a message to parent workspace"
      },
      "read-messages": {
        "usage": "",
        "desc": "Inspect available messages and disposition history without consuming or hiding anything."
      },
      "acknowledge": {
        "usage": "<message-id>",
        "desc": "Record that this AI pane observed one message without claiming its work."
      },
      "accept": {
        "usage": "<message-id>",
        "desc": "Claim one task for this AI pane; only its exact recipient can."
      },
      "complete": {
        "usage": "[options] <message-id>",
        "desc": "Record one immutable completed result for a task this AI pane accepted."
      },
      "fail": {
        "usage": "[options] <message-id>",
        "desc": "Record one immutable failed result for a task this AI pane accepted."
      },
      "task-status": {
        "usage": "<message-id>",
        "desc": "Inspect one task by UUID. Observational: reading changes nothing."
      },
      "tasks": {
        "usage": "[options]",
        "desc": "List tasks this Workspace or pane sent or received, including outstanding and unreachable ones."
      },
      "message-count": {
        "usage": "",
        "desc": "Get the pending message count for this pane without consuming"
      },
      "monitor": {
        "usage": "[options]",
        "desc": "Monitor pending messages. From an AI pane, returns immediately while any message still needs an explicit acknowledgement, acceptance, completion, or failure. Without a pane ID (a plain shell), waits for messages that arrive after it starts. Waits out DevSwarm restarts and outages, retrying with backoff; progress goes to stderr."
      },
      "help": {
        "usage": "[command]",
        "desc": "display help for command"
      }
    },
    "helpParsed": true
  },
  "dormantLog": {}
}
